"""Manual fill desk: explicit feedback, saved proposals and current cash."""
PANEL='''<style>
#manual-desk{background:#fff;padding:20px;margin:16px 0;border:1px solid #bad0df;border-radius:8px;overflow-wrap:anywhere}
#fill-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:14px}
#fill-form label{display:flex;flex-direction:column;min-width:0}#fill-form input,#fill-form select{box-sizing:border-box;width:100%;padding:9px}
#fill-form label:has(input[type=checkbox]){flex-direction:row;align-items:center;gap:8px;grid-column:1/-1}#fill-form input[type=checkbox]{width:auto}
#manual-desk button{font:inherit;padding:8px;cursor:pointer;max-width:100%}#fill-status{padding:12px;background:#eef4fa;white-space:pre-line}
#fill-status[data-kind=error]{background:#fff0ec;color:#8b291b}#fill-status[data-kind=success]{background:#e9f6ee;color:#245735}
#funding-summary{display:flex;flex-wrap:wrap;gap:12px}#funding-summary>div{padding:12px;border:1px solid #dbe3ea;border-radius:6px}#funding-summary b{display:block;font-size:20px}
#proposal-cards{max-height:360px;overflow:auto}.proposal-card{padding:12px;margin:10px 0;border:1px solid #dbe3ea;border-radius:6px}.proposal-card p{margin:6px 0}
#manual-desk table{min-width:760px}#positions table,#pending-reports table{min-width:640px}
</style><section id="manual-desk"><h2>手動成交回報與持倉</h2>
<p>成交儲存後會立即更新下方持倉、資金及歷史，不必等待下次掃描。這裡沒有下單功能。</p>
<div id="funding-summary" aria-live="polite"></div><p id="funding-asof"></p>
<h3>已確認持倉</h3><div id="positions"></div>
<h3>已回報買入、明細待補</h3><div id="pending-reports"></div>
<details id="proposal-history"><summary>從保存的操作建議帶入成交</summary><p>歷史建議會保留。帶入的是參考價與試算股數；請核對券商實際成交，改正金額、股數、價格及時間後，再勾選確認。歷史提案不代表現在仍建議買入。</p><div id="proposal-cards"></div></details>
<h3 id="fill-editor-title">手動新增或補齊成交</h3><p id="fill-source"></p>
<form id="fill-form" novalidate>
<label>股票代號<input name="symbol" placeholder="例如4063" required></label>
<label>買賣方向<select name="side"><option value="BUY">買進</option><option value="SELL">賣出</option></select></label>
<label>實際投入／收回金額 JPY（不含另列費用）<input name="amount_jpy" type="number" min="0.01" step="any" placeholder="例如20000"></label>
<label>每股實際成交價 JPY<input name="price" type="number" min="0.00000001" step="any" required></label>
<label>實際成交股數（最多8位小數）<input name="quantity" type="number" min="0.00000001" step="any" required></label>
<button id="calculate-shares" type="button">按金額與成交價試算股數</button>
<label>實際費用 JPY<input name="fees" type="number" min="0" step="any" value="0" required></label>
<label>實際成交日期時間（日本）<input name="filled_at" type="datetime-local" step="1" required></label>
<button id="fill-now" type="button">使用目前日本時間</button>
<label>固定失效價（選填）<input name="risk_lower" type="number" min="0.00000001" step="any"></label>
<label><input name="confirmed" type="checkbox">我確認已實際成交，並已核對股數、價格與時間</label>
<button id="fill-save" type="submit">儲存成交回報並更新持倉</button>
<label><input name="amount_reported" type="checkbox">明細尚未齊全，但我確認已實際投入上述金額，先保留資金</label>
<button id="save-pending" type="button">只保存已投入金額，明細稍後補</button>
<button id="clear-fill" type="button">改為新增另一筆</button>
</form><p id="fill-status" role="status" aria-live="assertive">請填寫實際成交，或從上方歷史建議帶入。</p>
<details><summary>已保存的成交歷史（含未確認紀錄）</summary><div id="fill-history"></div></details>
<p>確認成交會供下一輪三Agent判斷使用。明細待補的已投入金額先保留資金，不推定股數，也不自動加碼。</p>
<button id="analyze">執行固定名單三Agent分析</button> <span id="analysis-status"></span> <button id="reload-report" hidden>查看新報告</button>
<h3>決策通知</h3><p id="mail-status"></p><button id="flush-mail">寄送待寄決策事件</button>
</section><script>
const deskToken=__TOKEN__;const htmlReportAsOf=__ASOF__;const pageUIVersion=__UIVERSION__;
let deskFormDirty=false,fillBusy=false,activeDraft=null,lastDeskTime=0,deskPayload=null;
const newFillId=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
let pendingFillId=newFillId();
const fillForm=document.getElementById('fill-form');
const yen=v=>v==null?'未設定':Number(v).toLocaleString('zh-TW',{maximumFractionDigits:2});
function message(text,kind='info'){const e=document.getElementById('fill-status');e.textContent=text;e.dataset.kind=kind;}
async function postDesk(path,value){let r;try{r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Desk-Token':deskToken},body:JSON.stringify(value)});}catch(e){throw new Error('連線中斷，無法確認是否已儲存。請先查看成交歷史，或以同一表單重試，不要新增同一筆。');}let x;try{x=await r.json();}catch(e){throw new Error('程式回應不完整，請先檢查成交歷史；以同一表單重試可避免重複入帳。');}if(!r.ok)throw new Error(x.message||x.error||'操作未完成');return x;}
function element(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function table(headers,rows){const area=element('div');area.className='scroll';const t=element('table');const head=element('tr');headers.forEach(x=>head.append(element('th',x)));const thead=element('thead');thead.append(head);t.append(thead);const body=element('tbody');rows.forEach(cells=>{const row=element('tr');cells.forEach(x=>{const td=element('td');td.append(x instanceof Node?x:document.createTextNode(String(x)));row.append(td);});body.append(row);});t.append(body);area.append(t);return area;}
function draftIntoForm(d,plan=null){activeDraft=d;pendingFillId=d.fill_id;fillForm.elements.symbol.value=d.symbol;fillForm.elements.side.value=plan&&['EXIT_REVIEW','REDUCE_REVIEW'].includes(plan.action)?'SELL':'BUY';fillForm.elements.amount_jpy.value=d.amount_jpy??'';fillForm.elements.price.value=d.actual_price||plan&&plan.entry_reference||'';fillForm.elements.quantity.value=plan&&d.amount_jpy===plan.suggested_amount_jpy&&plan.suggested_shares||'';fillForm.elements.filled_at.value='';fillForm.elements.risk_lower.value='';fillForm.elements.confirmed.checked=false;fillForm.elements.amount_reported.checked=false;deskFormDirty=true;persistEditor();document.getElementById('fill-source').textContent='草稿已保存。'+(d.reported_executed?'已回報投入 '+yen(d.amount_jpy)+' 日圓；請補齊實際成交明細。':'以下價格／股數可能來自提案試算，尚未視為成交。');message('已帶入。請核對實際成交股數、價格、費用與日本時間，再勾選確認。');fillForm.scrollIntoView({block:'start',behavior:'smooth'});}
function applyDesk(d){const stamp=Date.parse(d.funding.funding_as_of);if(stamp<lastDeskTime)return;lastDeskTime=stamp;deskPayload=d;
const funding=document.getElementById('funding-summary');funding.replaceChildren();for(const [label,value] of [['設定本金 JPY',d.funding.capital_jpy],['目前可動用估計 JPY',d.funding.available_cash_estimate_jpy],['已回報、明細待補占用 JPY',d.funding.reserved_cash_jpy],['已確認持倉成本 JPY',d.funding.confirmed_cost_jpy]]){const box=element('div',label);box.append(element('b',yen(value)));funding.append(box);}
const fundingNote=document.getElementById('current-funding-note');if(fundingNote)fundingNote.textContent='依最新回報重算：可動用估計 '+yen(d.funding.available_cash_estimate_jpy)+' JPY；待補成交占用 '+yen(d.funding.reserved_cash_jpy)+' JPY。以下金額按目前資金重算，研究結論仍以原快照為準。';
document.getElementById('funding-asof').textContent='資金重算：'+d.funding.funding_as_of+'；研究快照：'+(d.funding.research_as_of||'尚無')+'。依你的設定及回報估算，並非券商同步餘額。';
const positions=document.getElementById('positions');positions.replaceChildren();const p=Object.values(d.portfolio.positions);if(p.length)positions.append(table(['標的','實際股數','平均成本JPY','持倉成本JPY','開倉時間'],p.map(x=>[x.symbol,x.quantity,yen(x.average_cost),yen(x.total_cost),x.opened_at])));else positions.textContent='尚無已確認持倉。明細待補的買入列在下方。';
const pending=document.getElementById('pending-reports');pending.replaceChildren();const drafts=d.drafts.filter(x=>x.reported_executed);if(drafts.length)pending.append(table(['標的','已投入JPY','已回報每股價JPY','狀態','操作'],drafts.map(x=>{const b=element('button','補齊這筆成交');b.onclick=()=>draftIntoForm(x);return[x.symbol,yen(x.amount_jpy),yen(x.actual_price),x.actual_price?'等待實際股數與時間':'等待實際股數、價格與時間',b];})));else pending.textContent='沒有待補的買入明細。';
const proposals=document.getElementById('proposal-cards');proposals.replaceChildren();for(const p of d.proposals){const card=element('div');card.className='proposal-card';card.append(element('b',p.symbol+' · '+p.name));card.append(element('p',p.as_of+' · '+(p.is_current?'本輪保存提案':'歷史提案，並非現在的買入指令')));card.append(element('p','原建議 '+yen(p.plan.suggested_amount_jpy)+' JPY；進場參考 '+yen(p.plan.entry_reference)+'；'+(p.fill_id?'已回報成交':'尚未連結確認成交')));const b=element('button',p.fill_id?'這份建議已回報':'帶入並微調已成交內容');b.disabled=!!p.fill_id;b.onclick=async()=>{try{const existing=p.draft_id&&d.drafts.find(x=>x.id===p.draft_id);const draft=existing||await postDesk('/api/fill-drafts',{symbol:p.symbol,amount_jpy:p.plan.suggested_amount_jpy>0?p.plan.suggested_amount_jpy:null,reported_executed:false,source_proposal_id:p.id});draftIntoForm(draft,{...p.plan,action:p.action});}catch(e){message(e.message,'error');}};card.append(b);proposals.append(card);}if(!proposals.children.length)proposals.textContent='目前沒有保存的有效操作提案；仍可手動回報實際成交。';
const history=document.getElementById('fill-history');history.replaceChildren();if(d.fill_history.length)history.append(table(['標的／方向','股數','價格JPY','實際時間','狀態','操作'],[...d.fill_history].reverse().map(x=>{let action='已保存';if(!x.confirmed&&!x.confirmed_later){const b=element('button','帶入核對後確認');b.onclick=()=>{activeDraft=d.drafts.find(t=>t.fill_id===x.id)||null;pendingFillId=x.confirmation_id;fillForm.elements.amount_jpy.value=x.quantity*x.price;for(const k of ['symbol','side','quantity','price','fees'])fillForm.elements[k].value=x[k];fillForm.elements.filled_at.value=new Date(Date.parse(x.filled_at)+9*3600000).toISOString().slice(0,19);fillForm.elements.confirmed.checked=false;deskFormDirty=true;message('已帶入未確認紀錄；核對後勾選確認，即可新增正式成交。');};action=b;}return[x.symbol+'／'+(x.side==='BUY'?'買進':'賣出'),x.quantity,yen(x.price),x.filled_at,x.confirmed?'已確認，計入持倉與資金':x.confirmed_later?'已另筆補確認':'未確認，不計入持倉',action];})));else history.textContent='尚無已保存成交。';
for(const plan of d.funding.plans){const row=document.querySelector('[data-funding-symbol="'+CSS.escape(plan.symbol)+'"]');if(row){for(const [key,value] of Object.entries(plan)){const cell=row.querySelector('[data-funding-field="'+key+'"]');if(cell)cell.textContent=typeof value==='number'?yen(value):value;}}}
}
async function refreshDesk(){try{const r=await fetch('/api/state');if(!r.ok)throw new Error('狀態讀取失敗');const s=await r.json();applyDesk(s.manual_desk);document.getElementById('flush-mail').disabled=s.email.status!=='READY';document.getElementById('mail-status').textContent='通知：'+({DISABLED:'已暫停',READY:'可寄送',NEEDS_GMAIL_APP_PASSWORD:'待設定Gmail憑證'}[s.email.status]||'待核對')+' · 待寄 '+(s.email.counts.PENDING||0)+' · 已寄 '+(s.email.counts.SENT||0);document.getElementById('analysis-status').textContent=s.runtime.analyze_text;document.getElementById('analyze').disabled=s.analysis.status==='RUNNING';document.getElementById('reload-report').hidden=!s.report_as_of||s.report_as_of===htmlReportAsOf;}catch(e){document.getElementById('funding-asof').textContent='目前無法更新持倉與資金，請保留輸入並確認程式仍在運行。';}}
function persistEditor(){try{const values={};for(const e of fillForm.elements){if(e.name&&e.type!=='checkbox')values[e.name]=e.value;}localStorage.setItem('jp-desk-fill-editor',JSON.stringify({values,id:pendingFillId,draft:activeDraft}));}catch(e){}}
fillForm.addEventListener('input',()=>{deskFormDirty=true;persistEditor();});fillForm.addEventListener('invalid',e=>message('請完成「'+(e.target.closest('label')?.textContent||'必要欄位')+'」後再儲存。','error'),true);
document.getElementById('calculate-shares').onclick=()=>{const a=Number(fillForm.elements.amount_jpy.value),p=Number(fillForm.elements.price.value);if(!(a>0&&p>0))return message('請先填入已投入金額與每股實際成交價。','error');fillForm.elements.quantity.value=(Math.floor(a/p*1e8)/1e8).toFixed(8);fillForm.elements.confirmed.checked=false;deskFormDirty=true;message('這是金額換算股數。請核對券商實際股數，必要時微調，再勾選確認。');};
document.getElementById('fill-now').onclick=()=>{fillForm.elements.filled_at.value=new Date(Date.now()+9*3600000).toISOString().slice(0,19);deskFormDirty=true;};
document.getElementById('clear-fill').onclick=()=>{try{localStorage.removeItem('jp-desk-fill-editor');}catch(e){}fillForm.reset();activeDraft=null;pendingFillId=newFillId();deskFormDirty=false;document.getElementById('fill-source').textContent='';message('已切換成新的一筆成交，尚未儲存。');};
document.getElementById('save-pending').onclick=async()=>{if(fillBusy)return;if(fillForm.elements.side.value!=='BUY'||!fillForm.elements.amount_reported.checked)return message('請選買進，並勾選「已實際投入上述金額，先保留資金」。','error');if(activeDraft&&activeDraft.reported_executed)return message('這筆金額已保留，請直接補齊明細後儲存成交；不會重複占用資金。');try{const d=await postDesk('/api/fill-drafts',{symbol:fillForm.elements.symbol.value,amount_jpy:Number(fillForm.elements.amount_jpy.value),reported_executed:true,actual_price:Number(fillForm.elements.price.value)||null,source_proposal_id:activeDraft&&activeDraft.source_proposal_id||null,id:activeDraft&&activeDraft.reported_executed?activeDraft.id:'amount-'+pendingFillId.slice(0,48)});activeDraft=d;pendingFillId=d.fill_id;fillForm.elements.confirmed.checked=false;deskFormDirty=false;message('已保存買入金額並保留資金，成交股數與成本尚未入帳。請補齊實際明細。','success');await refreshDesk();}catch(e){message(e.message,'error');}};
fillForm.addEventListener('submit',async e=>{e.preventDefault();if(fillBusy)return;message('正在檢查並儲存…');if(!fillForm.reportValidity())return;const f=new FormData(fillForm);let when=f.get('filled_at');if(when.length===16)when+=':00';const value={id:pendingFillId,symbol:f.get('symbol'),side:f.get('side'),quantity:Number(f.get('quantity')),price:Number(f.get('price')),fees:Number(f.get('fees')),filled_at:when+'+09:00',confirmed:f.has('confirmed')};if(f.get('risk_lower')&&value.side==='BUY')value.risk_reference={channel:'MANUAL',lower:Number(f.get('risk_lower')),price_basis:'raw_unverified',defined_at:new Date().toISOString(),anchor_at:null};const amount=f.get('amount_jpy');if(amount!==''&&Math.abs(Number(amount)-value.quantity*value.price)>1){message('投入金額與股數乘成交價不一致：依股數計算為 '+yen(value.quantity*value.price)+' JPY。請核對實際金額、股數與價格；費用另列。','error');return;}if(activeDraft)value.draft_id=activeDraft.id;fillBusy=true;let saved=false;document.getElementById('fill-save').disabled=true;try{const result=await postDesk('/api/fills',value);saved=true;deskFormDirty=false;fillForm.elements.confirmed.checked=false;if(!value.confirmed){pendingFillId=result.confirmation_id;persistEditor();}else{try{localStorage.removeItem('jp-desk-fill-editor');}catch(e){}}message(result.message,'success');if(result.manual_desk)applyDesk(result.manual_desk);await refreshDesk();}catch(x){message(saved?'紀錄已保存，但畫面更新失敗。請重新整理查看成交歷史，不要新增同一筆。':x.message,saved?'success':'error');}finally{fillBusy=false;document.getElementById('fill-save').disabled=false;}});
document.getElementById('analyze').onclick=async()=>{try{await postDesk('/api/analyze',{});await refreshDesk();}catch(x){message(x.message,'error');}};
document.getElementById('flush-mail').onclick=async()=>{try{await postDesk('/api/notifications/flush',{});await refreshDesk();}catch(x){document.getElementById('mail-status').textContent=x.message;}};
document.getElementById('reload-report').onclick=()=>location.reload();
document.addEventListener('DOMContentLoaded',()=>{try{const saved=JSON.parse(localStorage.getItem('jp-desk-fill-editor'));if(saved&&saved.values){for(const [k,v] of Object.entries(saved.values)){if(fillForm.elements.namedItem(k))fillForm.elements.namedItem(k).value=v;}pendingFillId=saved.id||newFillId();activeDraft=saved.draft||null;fillForm.elements.confirmed.checked=false;deskFormDirty=true;message('已恢復上次未清除的輸入，尚未自動入帳。請核對後再確認。');}}catch(e){}refreshDesk();setInterval(refreshDesk,5000);});
</script>'''
